'use strict';
let sceneTrimPoint=null;
const sceneTrimTools=document.createElement('span');sceneTrimTools.id='sceneTrimTools';sceneTrimTools.hidden=true;const markerLabel=document.createElement('strong');markerLabel.id='sceneTrimTime';sceneTrimTools.append(markerLabel,storyButton('Trim scene start here',()=>applySceneTrimPoint('start')),storyButton('Trim scene end here',()=>applySceneTrimPoint('end')));document.querySelector('.timeline-top').append(sceneTrimTools);
function selectSceneTrimPoint(s,at){stop();sceneIndex=project.scenes.indexOf(s);time=clamp(at,0,s.duration);sceneTrimPoint={sceneId:s.id,time};selectLayers([]);selectedAudio=null;timelineSelection={kind:'scene',id:s.id};render();draw()}
function applySceneTrimPoint(edge){try{const s=project.scenes.find(s=>s.id===sceneTrimPoint?.sceneId),at=sceneTrimPoint?.time;if(!s||!Number.isFinite(at))throw Error('Click the scene timeline to choose the cut point.');if(at<.05||at>s.duration-.05)throw Error('Choose a point inside the scene.');const plan=edge==='start'?planSceneHeadResize(s,at):planSceneHeadResize(s,0,at);Object.assign(project,plan);sceneIndex=project.scenes.findIndex(x=>x.id===s.id);time=edge==='start'?0:current().duration;sceneTrimPoint={sceneId:s.id,time};save();render();hydrateAudio();toast(edge==='start'?'Trimmed the scene before the crosshair.':'Trimmed the scene after the crosshair.')}catch(error){toast(error.message)}}
const timelineBeforeSceneMarker=renderTimeline;renderTimeline=function(){timelineBeforeSceneMarker();const selected=project.scenes.find(s=>s.id===sceneTrimPoint?.sceneId);sceneTrimTools.hidden=!selected;if(selected)markerLabel.textContent='Cut point '+sceneTrimPoint.time.toFixed(2)+'s';for(const el of document.querySelectorAll('.timeline-clip.scene[data-scene-index]')){const s=project.scenes[+el.dataset.sceneIndex];if(!s)continue;const cross=document.createElement('span');cross.className='scene-trim-crosshair';cross.style.left=(sceneTrimPoint?.sceneId===s.id?sceneTrimPoint.time:0)*timelineZoom+'px';cross.hidden=sceneTrimPoint?.sceneId!==s.id;el.append(cross);el.addEventListener('pointermove',e=>{if(timelineDrag||e.target.closest('.clip-edge,.scene-transition-point'))return;const local=clamp((e.clientX-el.getBoundingClientRect().left)/timelineZoom,0,s.duration);cross.hidden=false;cross.style.left=local*timelineZoom+'px';cross.title=local.toFixed(2)+'s'});el.addEventListener('pointerleave',()=>{if(sceneTrimPoint?.sceneId===s.id)cross.style.left=sceneTrimPoint.time*timelineZoom+'px';else cross.hidden=true});el.addEventListener('pointerdown',e=>{if(e.button||e.target.closest('.clip-edge,.scene-transition-point')||recording||window.editorTaskBusy)return;const local=clamp((e.clientX-el.getBoundingClientRect().left)/timelineZoom,0,s.duration);e.preventDefault();e.stopImmediatePropagation();selectSceneTrimPoint(s,Math.round(local*30)/30)},true)}};
sceneResizeStyle.textContent+='.scene-trim-crosshair{position:absolute;top:-6px;bottom:-6px;width:1px;border-left:2px solid #ffd982;pointer-events:none;z-index:10}.scene-trim-crosshair:before{content:"+";position:absolute;top:-5px;left:-7px;font-size:18px;color:#ffd982}#sceneTrimTools:not([hidden]){display:inline-flex;gap:7px;align-items:center}#sceneTrimTime{color:#ffd982;font-size:11px}';renderTimeline();
